where name = 'Институт гуманитарного образования и информационных технологий' and city = 'Москва';

update public.institutions set
  feedback_summary_student = 'Отзывы преимущественно положительные (около 90%): студенты отмечают структурированную подачу материала, преподавателей-практикующих юристов и адвокатов, а также насыщенную программу поездок и экскурсий (включая Госдуму). Стоимость обучения называют приемлемой. Из критики — низкий уровень части непрофильных предметов и заметная политизированность обучения.',
  feedback_positive_highlights = '{"преподаватели — практикующие юристы и адвокаты","насыщенная программа поездок и экскурсий","доступная стоимость обучения"}',
  feedback_negative_highlights = '{"низкий уровень части непрофильных предметов","заметная политизированность программы"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'Университет мировых цивилизаций имени В.В. Жириновского' and city = 'Москва';

update public.institutions set
  feedback_summary_student = 'Отзывы почти единогласно положительные: студенты отмечают тёплую, семейную атмосферу, индивидуальный подход и активное вовлечение в научную деятельность с первого курса. Институт ценят за практическую ориентацию — стажировки в госструктурах и международных компаниях, помощь деканата в трудоустройстве ещё во время учёбы. Явной систематической критики в открытых источниках почти не встречается.',
  feedback_positive_highlights = '{"тёплая семейная атмосфера и помощь деканата","активное вовлечение в науку с первого курса","стажировки в госструктурах и международных компаниях"}',
  feedback_negative_highlights = '{"систематической критики в открытых источниках почти не найдено"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'Институт международных экономических связей' and city = 'Москва';

update public.institutions set
  feedback_summary_student = 'Отзывы в основном положительные: студенты хвалят вежливых и профессиональных преподавателей, практико-ориентированную программу и гибкую систему скидок за высокие баллы ЕГЭ и хорошую учёбу. Отмечают, что вуз старается не отчислять студентов и помогает при трудностях на сессии. Критики в найденных источниках заметно меньше, чем позитива.',
  feedback_positive_highlights = '{"вежливые и профессиональные преподаватели","практико-ориентированная программа","гибкая система скидок на обучение"}',
  feedback_negative_highlights = '{"лояльная политика к отчислению вызывает вопросы к строгости требований"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'Московский университет имени А.С. Грибоедова' and city = 'Москва';

update public.institutions set
  feedback_summary_student = 'Отзывы очень положительные: небольшой камерный вуз с дружеской атмосферой, где около 80% преподавателей — практикующие востоковеды, а к студентам относятся по-человечески (можно напрямую обратиться к ректору или проректору). Изучение языков идёт в маленьких группах, что студенты особенно ценят. Из минусов — практически единственная и часто упоминаемая проблема: отсутствие общежития.',
  feedback_positive_highlights = '{"преподаватели — практикующие востоковеды","человеческое, внимательное отношение администрации","маленькие группы для изучения языков"}',
  feedback_negative_highlights = '{"отсутствие общежития"}',
  feedback_based_on_count = 4, feedback_generated_at = now(), updated_at = now()
where name = 'Институт стран Востока' and city = 'Москва';

update public.institutions set
  feedback_summary_student = 'Отзывы смешанные: студенты хвалят профильных преподавателей, совмещающих практику с преподаванием и следящих за новыми технологиями, а также насыщенную лабораторную и практическую работу вплоть до приглашений на работу после практики. Серьёзная критика касается вечерней/очно-заочной формы обучения — дезорганизация расписания, низкий контроль качества преподавания и неудобный график, из-за которого совмещать учёбу с работой сложно.',
  feedback_positive_highlights = '{"преподаватели-практики, следящие за новыми технологиями","много лабораторных и практических занятий","отзывчивый деканат"}',
  feedback_negative_highlights = '{"дезорганизация расписания на очно-заочной форме","неудобный график для работающих студентов"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'Инженерно-экономический институт Национального исследовательского университета МЭИ' and city = 'Москва';
